CREATE TABLE mail_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),mailbox text NOT NULL CHECK(mailbox IN('info','mail')),folder text NOT NULL,uidvalidity text NOT NULL,uid bigint NOT NULL,message_id text,thread_id text,subject text NOT NULL DEFAULT '',sender text NOT NULL DEFAULT '',recipients text NOT NULL DEFAULT '',body_text text NOT NULL DEFAULT '',body_html text NOT NULL DEFAULT '',flags jsonb NOT NULL DEFAULT '[]',received_at timestamptz,active boolean NOT NULL DEFAULT true,UNIQUE(mailbox,folder,uidvalidity,uid));
CREATE INDEX mail_message_search ON mail_messages(mailbox,folder,received_at DESC);
CREATE TABLE mail_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),message_id uuid NOT NULL REFERENCES mail_messages(id),position integer NOT NULL,name text NOT NULL,content bytea NOT NULL,mime text NOT NULL,UNIQUE(message_id,position));
CREATE TABLE mail_sync_state(mailbox text NOT NULL,folder text NOT NULL,last_synced timestamptz,status text NOT NULL,PRIMARY KEY(mailbox,folder));
CREATE TABLE mail_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),mailbox text NOT NULL CHECK(mailbox IN('info','mail')),recipient text NOT NULL DEFAULT '',subject text NOT NULL DEFAULT '',body text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now(),actor_id uuid NOT NULL REFERENCES users(id));
CREATE TABLE mail_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),message_id uuid NOT NULL REFERENCES mail_messages(id),kind text NOT NULL,resource_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
